mapper.select:
select setting_key as "settingKey", setting_value as "settingValue", unit as "unit", change_reason as "changeReason", updated_by as "updatedBy", updated_at as "updatedAt" from common_system_settings where setting_key in
#{key}
order by case setting_key when 'SESSION_IDLE_MINUTES' then 1 when 'PAGE_SIZE' then 2 when 'DEFAULT_SEARCH_PERIOD' then 3 when 'BULK_QUERY_THRESHOLD' then 4 when 'LONG_TASK_NOTICE_THRESHOLD' then 5 else 99 end
